UPDATE kb_document_change_note SET text = #{text}, base_version_id = #{baseVersionId}, note_version = #{noteVersion},
    corrected = corrected OR #{corrected}, created_after_visible = created_after_visible OR #{createdAfterVisible},
    updated_at = clock_timestamp() WHERE version_id = #{versionId} AND doc_id = #{documentId}

mapper.select:
SELECT id, doc_id, version_id, changed_at, text_before, text_after, base_before, base_after, visible_to_readers, reason
FROM kb_document_change_note_history WHERE doc_id = #{documentId} AND version_id = #{versionId}
AND (changed_at, id) < (#{beforeTime}, #{beforeId})
ORDER BY changed_at DESC, id DESC LIMIT #{limit}

